const { useState } = React;
const storageKey = 'lesson-demo:settings';

function Settings() {
  const [settings, setSettings] = useState({ theme: 'light', fontSize: 16 });

  function save() {
    localStorage.setItem(storageKey, JSON.stringify(settings));
    console.log(localStorage.getItem(storageKey));
  }

  return (
    <section>
      <p>테마: {settings.theme} / 글자: {settings.fontSize}px</p>
      <button type="button" onClick={() => setSettings({ ...settings, theme: settings.theme === 'light' ? 'dark' : 'light' })}>테마</button>
      <button type="button" onClick={() => setSettings({ ...settings, fontSize: settings.fontSize + 1 })}>글자 키우기</button>
      <button type="button" onClick={save}>저장</button>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Settings />);

